function GlassColorantSieveMaker.init() GlassColorantSieveMaker.ironStock=12; GlassColorantSieveMaker.bronzeStock=10; GlassColorantSieveMaker.woodStock=16; GlassColorantSieveMaker.leatherStock=10; GlassColorantSieveMaker.silverStock=8; GlassColorantSieveMaker.goldStock=6; GlassColorantSieveMaker.jewelStock=4; GlassColorantSieveMaker.pearlStock=4; GlassColorantSieveMaker.productStock={}; GlassColorantSieveMaker.buildings={}; GlassColorantSieveMaker.maker=nil; GlassColorantSieveMaker.activeMaking={}; GlassColorantSieveMaker.totalProducts=0; GlassColorantSieveMaker.dayTimer=0; print("[GlassColorantSieveMaker] Royal Glass Colorant Sieve Maker System initialized (6 products, 4 buildings)") end
function GlassColorantSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassColorantSieveMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",GlassColorantSieveMaker.maker.name,s),"success") end; return true end
function GlassColorantSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassColorantSieveMaker.build(id) local ok,e=GlassColorantSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassColorantSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassColorantSieveMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassColorantSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassColorantSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassColorantSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassColorantSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassColorantSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassColorantSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassColorantSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassColorantSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassColorantSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassColorantSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassColorantSieveMaker.buildings==0 then return false,"Potrebna sitnicna delavnica" end; if not GlassColorantSieveMaker.maker then return false,"Potreben sitnikar" end; return true end
function GlassColorantSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassColorantSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassColorantSieveMaker.ironStock=GlassColorantSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassColorantSieveMaker.bronzeStock=GlassColorantSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassColorantSieveMaker.woodStock=GlassColorantSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassColorantSieveMaker.leatherStock=GlassColorantSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassColorantSieveMaker.silverStock=GlassColorantSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassColorantSieveMaker.goldStock=GlassColorantSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassColorantSieveMaker.jewelStock=GlassColorantSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassColorantSieveMaker.pearlStock=GlassColorantSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassColorantSieveMaker.maker then t=math.max(1,t-math.floor(GlassColorantSieveMaker.maker.skill/13)) end; table.insert(GlassColorantSieveMaker.activeMaking,{id="glasscolorantsieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassColorantSieveMaker.completeMaking(m) local q=1.0+(GlassColorantSieveMaker.getQualityBonus()/100); if GlassColorantSieveMaker.maker then q=q+(GlassColorantSieveMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantSieveMaker.productStock[m.productType]=(GlassColorantSieveMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantSieveMaker.totalProducts=GlassColorantSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantSieveMaker.maker then GlassColorantSieveMaker.maker.itemsMade=GlassColorantSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantSieveMaker.maker.skill=math.min(100,GlassColorantSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorantsieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantSieveMaker.update(dt) if not _G.state then return end; GlassColorantSieveMaker.dayTimer=GlassColorantSieveMaker.dayTimer+dt; if GlassColorantSieveMaker.dayTimer>=30 then GlassColorantSieveMaker.dayTimer=0; for i=#GlassColorantSieveMaker.activeMaking,1,-1 do local m=GlassColorantSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantSieveMaker.completeMaking(m); table.remove(GlassColorantSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
